--
-- Table structure for table `player_teams`
--

DROP TABLE IF EXISTS `player_teams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_teams` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `player_id` bigint unsigned NOT NULL,
  `team_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_current_team` tinyint(1) NOT NULL DEFAULT '1',
  `joined_team_at` timestamp NULL DEFAULT NULL,
  `left_team_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `player_teams_player_id_foreign` (`player_id`),
  KEY `player_teams_team_id_foreign` (`team_id`),
  CONSTRAINT `player_teams_player_id_foreign` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`) ON DELETE CASCADE,
  CONSTRAINT `player_teams_team_id_foreign` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2568 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

